const dashboardToday="2026-07-23";
const inputDate=(date:Date)=>`${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,"0")}-${String(date.getDate()).padStart(2,"0")}`;
const displayDate=(value:string)=>new Intl.DateTimeFormat("en-IN",{day:"2-digit",month:"short",year:"numeric"}).format(new Date(`${value}T00:00:00`));
const timeGreeting=(date:Date|null)=>{if(!date)return"Hello";const hour=Number(new Intl.DateTimeFormat("en-GB",{timeZone:"Asia/Kolkata",hour:"2-digit",hour12:false}).format(date));return hour<12?"Good morning":hour<17?"Good afternoon":"Good evening";};
function leadActivityDate(lead:Lead){const text=`${lead.age || ""} ${lead.lastAction || ""}`;const iso=text.match(/(20\d{2})-(\d{2})-(\d{2})/);if(iso)return new Date(Number(iso[1]),Number(iso[2])-1,Number(iso[3]));const indian=text.match(/(\d{1,2})[-/]([01]?\d)[-/](20\d{2})/);if(indian)return new Date(Number(indian[3]),Number(indian[2])-1,Number(indian[1]));const ago=text.match(/(\d+)\s*(?:d|day)s?\s*ago/i);if(ago){const date=new Date(2026,6,22);date.setDate(date.getDate()-Number(ago[1]));return date;}if(/today|just now|now/i.test(text))return new Date(2026,6,22);return new Date(2026,3,1);}
const persistedLead = (row:any):Lead => ({ enq:row.enqNo, company:row.companyName, contact:row.clientName, email:row.email || "", phone:row.phone, city:row.city || "", website:row.website || "", highPotential:Boolean(row.highPotential), project:row.projectClass, bua:Number(row.builtUpAreaSqft || 0), source:row.enquirySource, status:row.status === "ENGAGED" ? "Engagement Initiated" : row.status === "PROPOSAL_SENT" ? "Proposal Sent" : row.status === "CONVERTED" ? "Converted" : row.status === "ON_HOLD" ? "On Hold" : row.status === "REJECTED" || row.status === "STOP" ? "Rejected" : "Lead Received", engagementType:row.engagementType||"", lastAction:row.lastAction || "", nextAction:row.nextAction || "", age:row.ageLabel || row.updatedAt || "", value:Number(row.proposalValue || 0), proposalNo:row.proposalNo || "" });

function Mark({ compact = false }: { compact?: boolean }) {
  return <div className={`brand ${compact ? "compact" : ""}`}><img src="/solutions-optispace-logo.png" alt="Solutions Optispace" width="626" height="196" loading="eager" decoding="sync" /></div>;
}

function Status({ value }: { value: Lead["status"] }) {
  return <span className={`status ${value.toLowerCase().replaceAll(" ", "-")}`}>{value === "STOP" ? "STOP · Under 5,000 SqFt" : value}</span>;
}

function highLevelAction(lead:Lead){
  const parts=(lead.nextAction || "").split("·").map(part=>part.trim()).filter(Boolean);
  const meaningful=parts.find(part=>!/^\d{4}-\d{2}-\d{2}$/.test(part)&&!/^(urgent|high|normal|low)$/i.test(part)&&!/^\d+$/.test(part));
  if(meaningful) return meaningful.length>72?`${meaningful.slice(0,69)}…`:meaningful;
  if(lead.status==="Proposal Sent") return "Proposal follow-up";
  if(lead.status==="Engagement Initiated") return "Client engagement follow-up";
  if(lead.status==="Converted") return "Project handover";
  if(lead.status==="On Hold") return "Review on-hold lead";
  if(lead.status==="Rejected" || lead.status==="STOP") return "No further action";
  return "Qualifying phone call";
}

function PaginationControls({total,page,pageSize,onPage,onPageSize}:{total:number;page:number;pageSize:number;onPage:(page:number)=>void;onPageSize:(size:number)=>void}){
  const pages=Math.max(1,Math.ceil(total/pageSize));const current=Math.min(page,pages);
  return <div className="pagination-controls"><label>Rows per page<select value={pageSize} onChange={event=>onPageSize(Number(event.target.value))}>{[10,25,50,100].map(size=><option value={size} key={size}>{size}</option>)}</select></label><span>Page {current} of {pages}</span><button disabled={current<=1} onClick={()=>onPage(current-1)} aria-label="Previous page">‹</button><button className="current">{current}</button><button disabled={current>=pages} onClick={()=>onPage(current+1)} aria-label="Next page">›</button></div>;
}

function PhaseCompanyList({companies,phaseIndex,onOpen}:{companies:Lead[];phaseIndex:number;onOpen:(lead:Lead)=>void}){
  const [pageSize,setPageSize]=useState(10);const [page,setPage]=useState(1);const pages=Math.max(1,Math.ceil(companies.length/pageSize));const safePage=Math.min(page,pages);const shown=companies.slice((safePage-1)*pageSize,safePage*pageSize);
  useEffect(()=>setPage(1),[pageSize,companies.length]);
  return <><div className="phase-companies">{shown.map(l=><button className={phaseIndex===3?`phase4-${l.status.toLowerCase().replaceAll(" ","-")}`:""} key={l.enq} onClick={()=>onOpen(l)}><b>{l.company}</b><small>{l.enq} · {l.status==="STOP"?"Rejected":l.status}{l.highPotential?" · High potential":""}</small></button>)}</div><PaginationControls total={companies.length} page={safePage} pageSize={pageSize} onPage={setPage} onPageSize={setPageSize}/></>;
}

