  const rawDefaultScope=Object.fromEntries(scopeCatalog.map(([id,,rate],index)=>[id,{enabled:proposal.payload?.scope?.[id]?.enabled??(index===0||(proposalType.includes("green")&&!proposalType.includes("light")&&index===1)),rate:Number(proposal.payload?.scope?.[id]?.rate??rate)}])) as Record<string,{enabled:boolean;rate:number}>;
