  const defaultTravel={km:Number(proposal.payload?.travel?.km)||0,kmRate:Number(proposal.payload?.travel?.kmRate)||20,days:Number(proposal.payload?.travel?.days)||0,people:Number(proposal.payload?.travel?.people)||2,stayRate:Number(proposal.payload?.travel?.stayRate)||5000};
  const [values,setValues]=useState({area:original.area,notes:"",scope:defaultScope,travel:defaultTravel});
  const [loading,setLoading]=useState(true),[saving,setSaving]=useState(false),[discountInputPercent,setDiscountInputPercent]=useState(0);
