  const save=async(event:FormEvent)=>{event.preventDefault();setSaving(true);const response=await fetch("/api/proposal-negotiations",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({proposalId:proposal.id,enqNo:proposal.enqNo,originalArea:original.area,negotiatedArea:original.area,originalProposalValue:original.proposalValue,negotiatedProposalValue,originalTravelValue:original.travelValue,negotiatedTravelValue,scope:values.scope,travel:values.travel,notes:values.notes})});const data=await response.json().catch(()=>({error:"Negotiation service returned an invalid response."}));setSaving(false);if(!response.ok){toast(data.error||"Negotiation could not be saved.");return;}toast(`Negotiation for ${proposal.proposalNo} saved.`);close();};
