type InvoiceRecord={id:number;invoiceNo:string;enqNo:string;mode:"Proforma"|"Tax";companyName:string;clientName:string;payload:any;createdAt:string;updatedAt:string};
function invoiceFinancials(row:InvoiceRecord,lead?:Lead){
  const details=row.payload?.details||{},basic=Number(details.basic??Math.round((lead?.value||0)*.75))||0,interstate=String(details.state||"Maharashtra").trim().toLowerCase()!=="maharashtra";
  const tax=basic*.18;
  const invoiceValue=Math.round(basic+tax),paymentReceived=Math.max(0,Number(details.paymentReceived)||0),remainingPayment=Math.max(0,invoiceValue-paymentReceived);
  return {invoiceValue,paymentReceived,remainingPayment,status:remainingPayment===0&&invoiceValue>0?"Paid":paymentReceived>0?"Partially paid":"Pending",interstate};
}
